fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cell: i32 = 8;
    let cols: i32 = w / cell;
    let rows: i32 = h / cell;
    let mut by: i32 = 0;
    while by < rows {
        let mut bx: i32 = 0;
        while bx < cols {
            let v: i32 = tab[(bx * 2 + t) & 31] + tab[(by * 3 + t * 2) & 31] + tab[(bx + by + t) & 31];
            let g: i32 = (v + 381) * 255 / 762;
            let b: i32 = 255 - g;
            host::display::fill_rect(bx * cell, by * cell, cell, cell, g * 256 + b);
            bx = bx + 1;
        }
        by = by + 1;
    }
    host::display::present();
}
